import time
import random
from itertools import combinations

_DEADLINE = time.time() + 115.0  # safety margin before 120s


# ---------- GF(16) arithmetic ----------
def _build_gf16():
    # field generated by x^4 + x + 1 (primitive)
    add = [0] * 16
    mul = [[0] * 16 for _ in range(16)]
    for a in range(16):
        for b in range(16):
            c = 0
            x = b
            for i in range(4):
                if a & (1 << i):
                    c ^= x
                x <<= 1
                if x & 16:
                    x ^= 0b10001  # reduce x^4 -> x + 1
            mul[a][b] = c
            add[a][b] = a ^ b
    inv = [0] * 16
    for a in range(1, 16):
        for b in range(1, 16):
            if mul[a][b] == 1:
                inv[a] = b
    return add, mul, inv


_ADD, _MUL, _INV = _build_gf16()


def _gf16_coloring(n):
    """Return (n, colors) for a valid 4-coloring of K_n (n<=16) via GF(16)."""
    # log table: log2(x) = k  <=>  2^k = x
    log = [0] * 16
    x = 1
    for k in range(16):
        log[x] = k
        x = _MUL[2][x]
    # discrete log of a*b: since log(a*b) = (log a + log b) mod 15
    # color = log(a+b) - log(a*b) mod 4  (well-defined: a+b and a*b nonzero for a!=b)
    colors = [0] * (n * (n - 1) // 2)
    idx = 0
    for a in range(n):
        for b in range(a + 1, n):
            s = _ADD[a][b]
            p = _MUL[a][b]
            c = (log[s] - (log[a] + log[b])) % 4
            colors[idx] = c
            idx += 1
    return n, colors


# ---------- C6 counting ----------
def _count_c6(colors, n, color):
    """Count 6-cycles (closed, ordered) of a single color, using bitsets."""
    adj = [0] * n
    idx = 0
    for a in range(n):
        m = 0
        for b in range(a + 1, n):
            if colors[idx] == color:
                m |= (1 << b)
            idx += 1
        adj[a] = m
    # also fill symmetric
    for a in range(n):
        m = adj[a]
        b = 0
        while m:
            lb = m & (-m)
            b = lb.bit_length() - 1
            adj[b] |= (1 << a)
            m ^= lb
    total = 0
    for a in range(n):
        na = adj[a]
        b = 0
        while na:
            lb = na & (-na)
            b = lb.bit_length() - 1
            if b > a:
                nb = adj[b]
                c = 0
                while nb:
                    lc = nb & (-nb)
                    c = lc.bit_length() - 1
                    if c > b:
                        nc = adj[c]
                        d = 0
                        while nc:
                            ld = nc & (-nc)
                            d = ld.bit_length() - 1
                            if d > c:
                                nd = adj[d]
                                e = 0
                                while nd:
                                    le = nd & (-nd)
                                    e = le.bit_length() - 1
                                    if e > d:
                                        ne = adj[e]
                                        f = 0
                                        while ne:
                                            lf = ne & (-ne)
                                            f = lf.bit_length() - 1
                                            if f > e:
                                                # need f adjacent to a, and a<b<c<d<e<f
                                                if (adj[f] >> a) & 1:
                                                    total += 1
                                            ne ^= lf
                                nd ^= ld
                        nc ^= lc
                nb ^= lc
            na ^= lb
    return total


def _count_all_c6(colors, n):
    return sum(_count_c6(colors, n, c) for c in range(4))


def _find_one_c6(colors, n, color):
    """Return a 6-cycle (tuple of 6 distinct vertices in order) of given color, or None."""
    adj = [0] * n
    idx = 0
    for a in range(n):
        m = 0
        for b in range(a + 1, n):
            if colors[idx] == color:
                m |= (1 << b)
            idx += 1
        adj[a] = m
    for a in range(n):
        m = adj[a]
        b = 0
        while m:
            lb = m & (-m)
            b = lb.bit_length() - 1
            if b > a:
                nb = adj[b]
                c = 0
                while nb:
                    lc = nb & (-nb)
                    c = lc.bit_length() - 1
                    if c > b:
                        nc = adj[c]
                        d = 0
                        while nc:
                            ld = nc & (-nc)
                            d = ld.bit_length() - 1
                            if d > c:
                                nd = adj[d]
                                e = 0
                                while nd:
                                    le = nd & (-nd)
                                    e = le.bit_length() - 1
                                    if e > d:
                                        ne = adj[e]
                                        f = 0
                                        while ne:
                                            lf = ne & (-ne)
                                            f = lf.bit_length() - 1
                                            if f > e and (adj[f] >> a) & 1:
                                                return (a, b, c, d, e, f)
                                            ne ^= lf
                                        nd ^= ld
                                nc ^= lc
                        nb ^= lc
                m ^= lb
    return None


def _edge_index(a, b, n):
    if a > b:
        a, b = b, a
    # number of pairs before row a: sum_{k=0}^{a-1} (n-1-k)
    # = a*(n-1) - a*(a-1)//2
    return a * (n - 1) - a * (a - 1) // 2 + (b - a - 1)


# ---------- local search to remove C6 ----------
def _try_fix_c6(colors, n, max_iters=200000):
    """Iteratively recolor edges to eliminate all monochromatic C6. Returns True if success."""
    # Precompute, for each color, the list of edges in that color (for fast recount delta).
    # We'll recount total C6 after each candidate recolor (only when it could help).
    for it in range(max_iters):
        if time.time() > _DEADLINE - 5.0:
            return False
        # find any color with a C6
        target_color = None
        cycle = None
        for c in range(4):
            if _count_c6(colors, n, c) > 0:
                target_color = c
                cycle = _find_one_c6(colors, n, c)
                break
        if cycle is None:
            return True
        # edges in the cycle (in order)
        cycle_edges = []
        for k in range(6):
            u = cycle[k]
            v = cycle[(k + 1) % 6]
            cycle_edges.append(_edge_index(u, v, n))
        # try to recolor one of these edges to a color that reduces total C6
        best = None
        base_total = _count_all_c6(colors, n)
        for ei in cycle_edges:
            cur = colors[ei]
            for newc in range(4):
                if newc == cur:
                    continue
                colors[ei] = newc
                t = _count_all_c6(colors, n)
                colors[ei] = cur
                if t < base_total:
                    if best is None or t < best[0]:
                        best = (t, ei, newc)
        if best is None:
            # no single recolor helps; try a random recolor of a cycle edge (hill-climbing escape)
            ei = random.choice(cycle_edges)
            newc = random.randint(0, 3)
            colors[ei] = newc
        else:
            _, ei, newc = best
            colors[ei] = newc
    return False


# ---------- main ----------
def construct():
    random.seed(12345)
    # guaranteed valid base: n=16
    n0, base = _gf16_coloring(16)

    # try to extend to 18, then 19 (and 17 as fallback)
    best_n, best_colors = n0, list(base)

    for target in (19, 18, 17):
        if time.time() > _DEADLINE - 30.0:
            break
        if target <= n0:
            # just truncate
            if target > best_n:
                best_n = target
                best_colors = base[:target * (target - 1) // 2]
            continue
        # build candidate: base 16 + new vertices with random colors
        extra = target - n0
        n = target
        total_edges = n * (n - 1) // 2
        colors = list(base)  # first 16*15//2 = 120 edges
        # edges involving new vertices (16..n-1)
        # For a in 16..n-1, b in a+1..n-1: index = a*(n-1) - a*(a-1)//2 + (b-a-1)
        # Also edges between old (0..15) and new (16..n-1): handled in base? No.
        # Recompute: base only covers pairs among 0..15. We must fill pairs involving new vertices.
        # Let's rebuild colors array of size total_edges.
        colors = [0] * total_edges
        # copy base pairs (both < 16)
        for a in range(16):
            for b in range(a + 1, 16):
                colors[_edge_index(a, b, n)] = base[_edge_index(a, b, 16)]
        # randomize edges involving new vertices
        for a in range(16):
            for b in range(16, n):
                colors[_edge_index(a, b, n)] = random.randint(0, 3)
        for a in range(16, n):
            for b in range(a + 1, n):
                colors[_edge_index(a, b, n)] = random.randint(0, 3)
        # now try to fix C6
        ok = _try_fix_c6(colors, n)
        if ok and _count_all_c6(colors, n) == 0:
            best_n = n
            best_colors = colors
            break  # got the largest we attempted; done
    return {'n': best_n, 'colors': best_colors}
